<?php $edit = !empty($product); ?><h2 class="mb-4"><?= $edit ? 'Edit Product' : 'Add Product' ?></h2><div class="card form-card"><div class="card-body p-4"><?php if(!empty($error)): ?><div class="alert alert-danger"><?= html_escape($error) ?></div><?php endif; ?><?= validation_errors('<div class="alert alert-danger">','</div>') ?><form method="post" enctype="multipart/form-data"><div class="row g-3"><div class="col-md-6"><label class="form-label">Product Name</label><input class="form-control" name="pr_name" value="<?= html_escape($edit?$product->pr_name:'') ?>" required></div><div class="col-md-6"><label class="form-label">Author Name</label><input class="form-control" name="pr_author_name" value="<?= html_escape($edit?$product->pr_author_name:'') ?>" required></div><div class="col-md-6"><label class="form-label">Price</label><input class="form-control" type="number" step="0.01" name="pr_price" value="<?= html_escape($edit?$product->pr_price:'') ?>" required></div><div class="col-md-6"><label class="form-label">Category</label><input class="form-control" name="pr_cate" value="<?= html_escape($edit?$product->pr_cate:'') ?>" required></div><div class="col-md-6"><label class="form-label">Quantity</label><input class="form-control" type="number" name="pr_qty" value="<?= html_escape($edit?$product->pr_qty:'') ?>" required></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="pr_desc" rows="4" required><?= html_escape($edit?$product->pr_desc:'') ?></textarea></div><div class="col-md-6"><label class="form-label">Product Image</label><input class="form-control" type="file" name="image" accept="image/*" <?= $edit?'':'required' ?>></div><div class="col-md-6 d-flex align-items-end gap-4"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_bestseller" value="1" <?= $edit&&!empty($product->is_bestseller)?'checked':'' ?>><label class="form-check-label">Best Seller</label></div><div class="form-check"><input class="form-check-input" type="checkbox" name="is_newarrival" value="1" <?= $edit&&!empty($product->is_newarrival)?'checked':'' ?>><label class="form-check-label">New Arrival</label></div></div></div><?php if($edit && !empty($product->image)): ?><img src="<?= product_image_url($product->image) ?>" class="mt-3 rounded" style="width:100px;height:100px;object-fit:cover"><?php endif; ?><div class="mt-4"><a href="<?= site_url('admin/products') ?>" class="btn btn-light">Cancel</a> <button class="btn btn-primary"><?= $edit?'Update Product':'Add Product' ?></button></div></form></div></div>
